def pool_max(img, size=2):
    out = []
    for y in range(0, len(img) - size + 1, size):
        row = []
        for x in range(0, len(img[0]) - size + 1, size):
            block = [img[y + dy][x + dx] for dy in range(size) for dx in range(size)]
            row.append(max(block))
        out.append(row)
    return out

