img = [[0, 0], [255, 255]]

def histogram(img, bins=2):
    step = 256 / bins
    counts = [0] * bins
    for row in img:
        for v in row:
            counts[min(int(v / step), bins - 1)] += 1
    return counts

print(histogram(img))

scene = [
