image = [
    [1, 2, 3],
    [4, 5, 6],
    [7, 8, 9],
]

def flip_horizontal(img):
    return [list(reversed(row)) for row in img]

def rotate90(img):
    return [list(row) for row in zip(*reversed(img))]

def brighter(img, delta):
    return [[min(9, v + delta) for v in row] for row in img]

variants = [
    ("оригинал", image),
    ("отражение", flip_horizontal(image)),
    ("поворот 90", rotate90(image)),
    ("ярче на 2", brighter(image, 2)),
]

for name, result in variants:
    print(name)
    for row in result:
        print("  ", row)

